window.__finlexDocLoaded(10200,{"id":10200,"articles":[{"id":1000831,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Governs determination of functional currency, remeasurement of foreign currency transactions, translation of foreign entity financial statements (current rate method with CTA in OCI), and highly inflationary economies (>=100% 3-year cumulative inflation).","seq":0},{"id":1000832,"no":"ASC 830-10 / 830-30","heading":"Functional Currency, Translation & Highly Inflationary Economies","text":"• Functional Currency (ASC 830-10-45): Determined by evaluating economic indicators (cash flows, sales prices, sales market, expenses, financing, intercompany) without a strict primary/secondary hierarchy.\n• Translation (ASC 830-30): Assets/liabilities at closing rate, P&L at weighted-average rate, Cumulative Translation Adjustment (CTA) in OCI.\n• Highly Inflationary Economies (ASC 830-10-45-11): Bright-line >= 100% cumulative 3-year inflation requires remeasuring the foreign entity as if the reporting currency (e.g., USD) were its functional currency.","seq":1},{"id":1000833,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Highly Inflationary Accounting: ASC 830 switches functional currency to the parent's reporting currency (temporal remeasurement); IAS 29 restates local-currency statements using a general price index before translating at the closing rate.","seq":2},{"id":1000834,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
